def get_card(card_id: str) -> dict[str, Any] | None:
    for card in CARDS:
        if card["id"] == card_id:
            return card
    return None


def transactions_for_card(card_id: str) -> list[dict[str, Any]]:
    return list(TRANSACTIONS_BY_CARD_ID.get(card_id, []))


def format_transactions_text(transactions: list[dict[str, Any]]) -> str:
    if not transactions:
        return ""
    return "\n".join(f"- {tx['line']}" for tx in transactions)


def transaction_tool_result(
    transactions: list[dict[str, Any]],
    *,
    card_label: str | None = None,
) -> dict[str, Any]:
    """Customer-facing full list plus structured rows for the LLM (ids for reporting)."""
    lines = format_transactions_text(transactions)
    if card_label and lines:
        display = f"Recent charges on {card_label}:\n{lines}"
    elif lines:
        display = "Recent charges:\n" + lines
    else:
        display = ""
    return {
        "transaction_available": bool(transactions),
        "count": len(transactions),
        "transactions_display_text": display,
        "transactions": [{"id": tx["id"], "line": tx["line"]} for tx in transactions],
    }


def match_charges(
    charge_descriptions: list[str],
    transactions: list[dict[str, Any]],
) -> list[dict[str, Any]]:
    matched: list[dict[str, Any]] = []
    for description in charge_descriptions:
        needle = description.lower()
        for tx in transactions:
            if needle in tx["line"].lower() or needle in tx["merchant"].lower():
                if tx not in matched:
                    matched.append(tx)
    return matched
